<dialog id='product-details' class='report-dialog' aria-labelledby='product-details-title'><div class='report-heading'><h2 id='product-details-title'>Produtos mais pedidos</h2><button type='button' data-close-report>Fechar</button></div><div class='scroll'><table><thead><tr><th>Produto</th><th>Categoria</th><th>Quantidade</th><th>Pedidos com o produto</th></tr></thead><tbody id='production-products'></tbody></table></div></dialog>
